import javax.swing.*;import java.awt.*;import java.awt.event.*;
public class StylesDemo{static double convert(String s){double n=Double.parseDouble(s);if(n<0)throw new IllegalArgumentException();return n*.012;}
static class Base extends JFrame{JTextField amount=new JTextField("100",10);JLabel result=new JLabel("Result");JButton button=new JButton("Convert");Base(String t){super(t);setLayout(new FlowLayout());add(amount);add(button);add(result);setSize(350,130);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);}void run(){try{result.setText(String.format("%.2f USD",convert(amount.getText())));}catch(Exception e){result.setText("Invalid amount");}}}
static class Implements extends Base implements ActionListener{Implements(){super("Implements");button.addActionListener(this);amount.addActionListener(this);}public void actionPerformed(ActionEvent e){run();}}
static class Named extends Base{class Handler implements ActionListener{public void actionPerformed(ActionEvent e){run();}}Named(){super("Named inner");Handler h=new Handler();button.addActionListener(h);amount.addActionListener(h);}}
static class Anonymous extends Base{Anonymous(){super("Anonymous inner");ActionListener h=new ActionListener(){public void actionPerformed(ActionEvent e){run();}};button.addActionListener(h);amount.addActionListener(h);}}
static class Lambda extends Base{Lambda(){super("Lambda");button.addActionListener(e->run());amount.addActionListener(e->run());}}
public static void main(String[]a){SwingUtilities.invokeLater(()->{String[]o={"Implements","Named inner","Anonymous inner","Lambda"};String s=(String)JOptionPane.showInputDialog(null,"Choose event style","Styles",0,null,o,o[3]);Base f=s==null||s.equals(o[3])?new Lambda():s.equals(o[0])?new Implements():s.equals(o[1])?new Named():new Anonymous();f.setVisible(true);});}}
